#define _GNU_SOURCE
#include <fcntl.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
extern char **environ;
extern char *program_invocation_short_name;
static void write_all(int fd, const char *s) {
    size_t n = strlen(s);
    if (write(fd, s, n) != (ssize_t)n) _exit(121);
}
__attribute__((constructor)) static void entry(void) {
    if (!program_invocation_short_name || strcmp(program_invocation_short_name,"make")) return;
    int fd=open("seen",O_WRONLY|O_APPEND|O_CLOEXEC);
    if (fd<0) _exit(122);
    write_all(fd,"ENTRY\n");
    for(char **slot=environ; *slot; ++slot) {
        if (!strncmp(*slot,"RMKEEP_",7) || !strncmp(*slot,"MAKELEVEL=",10)
            || !strncmp(*slot,"MAKE_RESTARTS=",14)) {
            write_all(fd,*slot);
            write_all(fd,"\n");
        }
    }
    if (close(fd)) _exit(123);
    if (!getenv("RMKEEP_LIVE") && setenv("RMKEEP_LIVE","set-in-loader",1)) _exit(124);
}
